//! Full-source Living ritual composes a real token choice and attachment transaction.
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone,Effect};
use ironsmith::effects::{execute_effect,EffectContext};
use ironsmith::target::ChooseSpec;
use ironsmith::decision::DecisionMaker;
use ironsmith::triggers::TriggerQueue;
use ironsmith_compiled_artifact::CompiledCardArtifact;
use ironsmith_core::custom_subtypes::CustomSubtypeDefinition;
use ironsmith_core::SubtypeFamily;
const A:PlayerId=PlayerId(0);
fn definitions(name:&str,text:&str)->[CardDefinition;2]{let(result,loss)=ironsmith_compiler::parse_loss::capture(||ironsmith_compiler::with_custom_subtypes(&[CustomSubtypeDefinition{singular:"Implement".into(),plural:"Implements".into(),family:SubtypeFamily::Artifact}],||ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact(name,text,false))).unwrap());assert!(!loss.is_lossy(),"{}",loss.reasons_text());let(artifact,direct)=result.unwrap();let restored=CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&restored).unwrap()]}
struct Choice(usize);
impl DecisionMaker for Choice{fn decide_options(&mut self,_:&GameState,ctx:&ironsmith::decisions::context::SelectOptionsContext)->Vec<usize>{ctx.options.iter().find(|o|o.legal&&o.index==self.0).or_else(||ctx.options.iter().find(|o|o.legal)).map(|o|vec![o.index]).unwrap_or_default()}}
#[test]
fn exact_source_chooses_devils_or_full_named_token_and_checks_distinct_implement_names(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/msem-abilities-tail.json")).unwrap();let row=fixture["mechanics"].as_array().unwrap().iter().find(|m|m["id"]=="msem-924").unwrap();let card=&row["representative_cards"][0];for definition in definitions(card["name"].as_str().unwrap(),card["executable_text"].as_str().unwrap()){for choice in [0,1]{for distinct in [false,true]{let mut game=GameState::new(vec!["A".into(),"B".into()],20);for i in 0..2{let name=if distinct{format!("Other implement {i}")}else{"Other implement".to_string()};let helper=definitions(&name,"Type: Artifact — Implement")[0].clone();game.create_object_from_definition(&helper,A,Zone::Battlefield);}
 let source=game.create_object_from_definition(&definition,A,Zone::Hand);let stable=game.object(source).unwrap().stable_id;execute_effect(&mut game,&Effect::move_to_zone(ChooseSpec::Source,Zone::Battlefield,false),&mut EffectContext::new_default(source,A)).unwrap();let mut queue=TriggerQueue::new();let mut dm=Choice(choice);for _ in 0..6{ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut dm).unwrap();if game.stack.is_empty(){break}ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut dm).unwrap();}
 let arrived=game.find_object_by_stable_id(stable).unwrap();let creatures:Vec<_>=game.battlefield.iter().copied().filter(|id|game.object(*id).unwrap().card_types.contains(&ironsmith::CardType::Creature)).collect();let should_remain=choice==0||distinct;assert_eq!(creatures.len(),usize::from(should_remain));if should_remain{let token=creatures[0];assert_eq!(game.object(arrived).unwrap().attached_to,Some(ironsmith::object::AttachmentTarget::Object(token)));if choice==0{assert!(game.object(token).unwrap().subtypes.contains(&ironsmith::types::Subtype::Devil));assert!(game.object(token).unwrap().colors().contains(ironsmith::color::Color::Red));assert_eq!(game.current_power(token),Some(3));assert_eq!(game.current_toughness(token),Some(2));}else{assert_eq!(game.current_name(token).as_deref(),Some("Sulmina, the Final Age"));assert!(game.object(token).unwrap().supertypes.contains(&ironsmith::types::Supertype::Legendary));assert!(game.object(token).unwrap().has_static_ability_id(ironsmith::static_abilities::StaticAbilityId::Flying));assert!(game.object(token).unwrap().has_static_ability_id(ironsmith::static_abilities::StaticAbilityId::Indestructible));assert!(game.object(token).unwrap().colors().contains(ironsmith::color::Color::Black));assert!(game.object(token).unwrap().subtypes.contains(&ironsmith::types::Subtype::Demon));assert_eq!(game.current_power(token),Some(5));assert_eq!(game.current_toughness(token),Some(4));}}else{assert_eq!(game.object(arrived).unwrap().attached_to,None);}
 }}}}
